const interactions=()=>`<div class="lightbox" id="site-lightbox" hidden role="dialog" aria-modal="true" aria-labelledby="lightbox-caption"><button class="lightbox-close" type="button" aria-label="Close photograph">&times;</button><button class="lightbox-prev" type="button" aria-label="Previous photograph">&#8249;</button><figure><img id="lightbox-image" alt=""><figcaption id="lightbox-caption"></figcaption></figure><button class="lightbox-next" type="button" aria-label="Next photograph">&#8250;</button></div><script>(()=>{const toggle=document.querySelector('.menu-toggle'),menu=document.getElementById('site-menu');if(toggle&&menu){toggle.addEventListener('click',()=>{const open=menu.classList.toggle('is-open');toggle.setAttribute('aria-expanded',String(open))});menu.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>{menu.classList.remove('is-open');toggle.setAttribute('aria-expanded','false')}))}const items=[...document.querySelectorAll('[data-lightbox]')],box=document.getElementById('site-lightbox'),image=document.getElementById('lightbox-image'),caption=document.getElementById('lightbox-caption'),previous=box.querySelector('.lightbox-prev'),next=box.querySelector('.lightbox-next'),close=box.querySelector('.lightbox-close');let current=0,lastFocus=null;const show=index=>{current=(index+items.length)%items.length;const item=items[current],inside=item.querySelector('img');image.src=item.dataset.src||item.getAttribute('href');image.alt=item.dataset.alt||(inside&&inside.alt)||'';caption.textContent=item.dataset.caption||image.alt;previous.hidden=next.hidden=items.length<2};const open=index=>{lastFocus=document.activeElement;show(index);box.hidden=false;document.body.classList.add('lightbox-open');close.focus()};const shut=()=>{box.hidden=true;image.removeAttribute('src');document.body.classList.remove('lightbox-open');if(lastFocus)lastFocus.focus()};items.forEach((item,index)=>item.addEventListener('click',event=>{event.preventDefault();open(index)}));previous.addEventListener('click',()=>show(current-1));next.addEventListener('click',()=>show(current+1));close.addEventListener('click',shut);box.addEventListener('click',event=>{if(event.target===box)shut()});document.addEventListener('keydown',event=>{if(box.hidden)return;if(event.key==='Escape')shut();if(event.key==='ArrowLeft')show(current-1);if(event.key==='ArrowRight')show(current+1)})})();</script>`;
function page({path,title,description,body,json=[],image="/opengraph.jpg",imageAlt=title}){const socialImage=image.startsWith("http")?image:`https://www.steelstud.ca${image}`;const ogType=path.startsWith("/projects/")?"article":"website";return `<!doctype html><html lang="en-CA"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title><meta name="description" content="${esc(description)}"><meta name="robots" content="index,follow,max-image-preview:large"><link rel="canonical" href="${canonical(path)}"><link rel="icon" href="/favicon.svg"><link rel="stylesheet" href="/styles.css"><link rel="stylesheet" href="/floater.css"><meta property="og:type" content="${ogType}"><meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(description)}"><meta property="og:url" content="${canonical(path)}"><meta property="og:image" content="${socialImage}"><meta property="og:image:alt" content="${esc(imageAlt)}"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="${esc(title)}"><meta name="twitter:description" content="${esc(description)}"><meta name="twitter:image" content="${socialImage}">${json.join("")}</head><body>${header()}<main>${body}</main>${footer()}${interactions()}</body></html>`}
async function emit(path,html){
  const dir=path==="/"?dist:join(dist,path);
  await mkdir(dir,{recursive:true});
  await writeFile(join(dir,"index.html"),html);
}
