await emit("/",page({path:"/",title:"Ceilings, Walls & Floors Vancouver | SteelStud.ca",description:"SteelStud.ca builds complete Metro Vancouver interiors: steel stud framing, drywall, ceilings, flooring and tenant improvements backed by 35 years of contracting experience.",json:[org],body:`<section class="hero"><div class="wrap"><div class="eyebrow">Vancouver interior construction</div><h1>Ceilings. Walls. Floors.</h1><p>A complete interior scope backed by ${business.yearsSteel} years specializing in steel stud framing and ${business.yearsContracting} years of general contracting experience for strata, condominium, commercial and residential properties.</p><div class="actions"><a class="btn" href="tel:${business.phoneHref}">Call ${business.phone}</a><a class="btn alt" href="#services">View services</a></div></div></section><section class="section"><div class="wrap"><div class="stats"><div class="stat"><strong>35+</strong>years general contracting</div><div class="stat"><strong>16+</strong>years steel stud specialization</div><div class="stat"><strong>One scope</strong>ceilings, walls and floors</div></div></div></section><section class="section alt" id="services"><div class="wrap"><div class="eyebrow">Complete interior scope</div><h2>From framing to finished floor</h2><p class="lede">One experienced team for steel and wood framing, drywall, ceilings, flooring, textures, repairs and tenant improvements.</p><div class="grid">${cards}</div></div></section><section class="section"><div class="wrap split"><div><div class="eyebrow">A business history recovered</div><h2>Flooring expertise is part of the story</h2><p class="lede">Before COVID, FlooringInstaller.ca presented our commercial and residential flooring work across Vancouver and the Lower Mainland. The website was lost, but the experience was not. SteelStud.ca now carries that capability forward as part of a coordinated interior scope.</p><p>Our archived work included engineered hardwood, laminate, vinyl plank, carpet tile, tile, repairs and supply-and-install projects for homeowners, strata, developers, builders, offices, stores and restaurants.</p><a class="btn" href="/flooring">Explore flooring installation</a></div><img src="/images/archive/office-carpet-buildout-flooringinstaller.jpeg" alt="Finished commercial carpet tile installation in a small office from the FlooringInstaller.ca archive"></div></section><section class="section alt"><div class="wrap"><div class="eyebrow">The right place in the network</div><h2>Specialist execution, connected when the project grows</h2><div class="grid"><article class="card"><div class="card-body"><h3>SteelStud.ca</h3><p>Hands-on interior execution for ceilings, walls, floors, framing, drywall and focused buildouts.</p></div></article><article class="card"><div class="card-body"><h3>Tenant Improvement Contractors</h3><p>Broader commercial tenant-improvement planning, multi-trade coordination and complete business-space delivery.</p><a href="https://tenantimprovementcontractors.com/" rel="noopener">Visit TIC →</a></div></article><article class="card"><div class="card-body"><h3>Strata & acoustic specialists</h3><p>Property-wide strata programs belong with Strata Property Services; specialist acoustic design and systems connect to Acustiq.</p><a href="https://stratapropertyservices.com/" rel="noopener">Strata services →</a> · <a href="https://acustiq.ca/" rel="noopener">Acustiq →</a></div></article></div></div></section><section class="section"><div class="wrap split"><div><div class="eyebrow">First-hand work</div><h2>Built on real project experience</h2><p class="lede">The strongest proof is the work itself. Our project library documents actual ceiling, framing, drywall and flooring assemblies completed across the Lower Mainland.</p><a class="btn" href="/projects">View project evidence</a></div><img src="/images/real-tbar-ceiling-example.jpg" alt="Installed suspended T-bar acoustic ceiling"></div></section>`}));
for(const s of services){const path=`/${s.slug}`;const faqs=[`What does ${s.name.toLowerCase()} include?`,`Does SteelStud.ca provide ${s.name.toLowerCase()} across Metro Vancouver?`,`Can this work be completed in an occupied strata or commercial building?`];await emit(path,page({path,title:`${s.name} Vancouver & Metro Vancouver | SteelStud.ca`,description:`Professional ${s.name.toLowerCase()} for strata, commercial and residential interiors across Metro Vancouver. Call ${business.phone}.`,json:[org,schema("Service",{name:s.name,provider:{"@id":"https://www.steelstud.ca/#business"},areaServed:cities.map(c=>c.name)})],body:`<div class="wrap crumbs"><a href="/">Home</a> / ${s.name}</div><section class="page-hero"><div class="wrap"><div class="eyebrow">Metro Vancouver contractors</div><h1>${s.name}</h1><p class="lede">${s.short}</p></div></section><section class="section"><div class="wrap split"><div><h2>Scope built around the property</h2><p>Every project begins with the existing conditions, access, drawings and finish requirements. We coordinate the assembly so framing, services, board and final finish work together.</p><ul class="checklist">${s.details.map(x=>`<li>${x}</li>`).join("")}</ul></div><img src="/images/${s.image}" alt="${s.name} project"></div></section><section class="section alt"><div class="wrap"><h2>Where this service fits</h2><p class="lede">SteelStud.ca works in condominiums, strata buildings, offices, retail units, mixed-use properties and homes throughout the Lower Mainland. Occupied sites receive careful scheduling, dust control and communication.</p><h3>Related expertise</h3><p>${services.filter(x=>x.slug!==s.slug).slice(0,5).map(x=>`<a href="/${x.slug}">${x.name}</a>`).join(" · ")}</p></div></section><section class="section faq"><div class="wrap"><h2>${s.name} questions</h2>${faqs.map((q,i)=>`<details><summary>${q}</summary><p>${i===0?`The exact scope is confirmed after reviewing the property, drawings and desired finish. Common work includes ${s.details.join(", ").toLowerCase()}.`:i===1?`Yes. We serve ${cities.map(c=>c.name).join(", ")}.`:`Yes. We plan access, working hours, protection and cleanup around residents, tenants and property-management requirements.`}</p></details>`).join("")}</div></section>`}))}


