for(const c of bathroomCities){const path=`/bathroom-renovations/${c.slug}`;const faqs=[[`What bathroom renovation work do you provide in ${c.name}?`,`Scopes can include demolition, framing, backing, drywall, waterproofing coordination, custom showers, tubs, tile, flooring, vanities, fixtures and finish work.`],[`Can you work in an occupied ${c.name} condo?`,`Yes. We plan building approvals, access, approved hours, elevator protection, plumbing shut-downs, dust control and cleanup around residents.`],[`Do you provide a written bathroom renovation quote?`,`Yes. A site review confirms existing conditions, product selections, responsibilities, exclusions, sequence and the work included in the quote.`]];const faqSchema=schema("FAQPage",{mainEntity:faqs.map(([q,a])=>({"@type":"Question",name:q,acceptedAnswer:{"@type":"Answer",text:a}}))});await emit(path,page({path,title:`Bathroom Renovation Contractors ${c.name} | SteelStud.ca`,description:`Bathroom renovations in ${c.name}, BC: custom showers, bathroom tile, drywall, framing, vanities, heated-floor coordination and occupied-condo planning.`,json:[org,schema("Service",{name:`Bathroom renovations in ${c.name}`,serviceType:"Bathroom remodeling",provider:{"@id":"https://www.steelstud.ca/#business"},areaServed:{"@type":"City",name:c.name}}),faqSchema],body:`<div class="wrap crumbs"><a href="/">Home</a> / <a href="/bathroom-renovations">Bathroom renovations</a> / ${c.name}</div><section class="page-hero"><div class="wrap"><div class="eyebrow">Local bathroom contractors</div><h1>Bathroom renovations in ${c.name}</h1><p class="lede">Custom showers, tubs, tile, vanities and complete bathroom interiors coordinated from the structure behind the wall to the finished floor.</p></div></section><section class="section"><div class="wrap split"><div><h2>Bathroom remodelling planned for ${c.name} properties</h2><p>${c.local}</p><p>We begin with the existing room, plumbing and ventilation, then coordinate framing, backing, drywall, waterproofing, shower slopes, floor elevations, tile transitions and fixtures as one interior assembly.</p><ul class="checklist"><li>Condo and residential bathroom renovations</li><li>Custom tiled showers and tub surrounds</li><li>Bathroom floor and wall tile</li><li>Vanities, mirrors and accessories</li><li>Heated-floor and service coordination</li><li>Protection and daily cleanup for occupied properties</li></ul></div><img src="/images/service-bathroom-renovations.jpg" alt="Custom tiled shower demonstrating bathroom renovation work in ${c.name}"></div></section><section class="section alt"><div class="wrap"><h2>When the project is larger than one bathroom</h2><p>For multi-suite or property-wide programs, visit <a href="https://stratapropertyservices.com/" rel="noopener">Strata Property Services</a>. For commercial washrooms and complete business-space renovations, visit <a href="https://tenantimprovementcontractors.com/" rel="noopener">Tenant Improvement Contractors</a>.</p></div></section><section class="section faq"><div class="wrap"><h2>${c.name} bathroom renovation questions</h2>${faqs.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join("")}</div></section>`}))}

