await emit("/",page({path:"/",title:"Commercial Steel Stud Framing Vancouver | SteelStud.ca",description:"Metro Vancouver commercial steel stud framing contractors for partitions, drywall, suspended ceilings and tenant improvements. Call 604-761-1518.",json:[org],image:"/images/archive/building-suites.jpg",imageAlt:"Commercial steel stud framing by SteelStud.ca",body:`<section class="hero"><div class="wrap"><div class="eyebrow">Commercial interior construction · Metro Vancouver</div><h1>Steel stud framing, drywall & ceilings</h1><p>Commercial partitions, bulkheads, ceiling systems and complete wall assemblies built by a contractor with ${business.yearsSteel} years specializing in steel framing and ${business.yearsContracting} years of construction experience.</p><div class="actions"><a class="btn" href="tel:${business.phoneHref}">Call ${business.phone}</a><a class="btn alt" href="/projects">See real project work</a></div></div></section><section class="section"><div class="wrap"><div class="stats"><div class="stat"><strong>Steel first</strong>commercial partitions and framing</div><div class="stat"><strong>Complete walls</strong>board, tape and finish</div><div class="stat"><strong>Ceiling systems</strong>T-bar, drops and features</div></div></div></section><section class="section alt" id="services"><div class="wrap"><div class="eyebrow">Core services</div><h2>Built around commercial framing</h2><p class="lede">SteelStud.ca focuses on the assemblies that shape commercial, strata and multi-unit interiors: framing, drywall, ceilings, insulation and coordinated tenant-improvement work.</p><div class="grid">${cards}</div></div></section><section class="section"><div class="wrap split"><div><div class="eyebrow">Framing contractors</div><h2>Layout, structure and coordination before the walls close</h2><p class="lede">Good steel framing controls the dimensions of the finished interior. We coordinate partition layout, door and glazing openings, backing, bulkheads, ceiling elevations and service clearances before drywall hides the work.</p><ul class="checklist"><li>Commercial partitions and demising walls</li><li>Office, retail and strata interior buildouts</li><li>Bulkheads, soffits and architectural ceiling framing</li><li>Backing for millwork, fixtures, displays and equipment</li><li>Fire and acoustic assembly coordination</li></ul><a class="btn" href="/framing-in-steel">View steel framing services</a></div><img src="/images/archive/building-suites.jpg" alt="Commercial steel stud partitions under construction"></div></section><section class="section alt"><div class="wrap split"><div><div class="eyebrow">Finishing scope</div><h2>Commercial flooring when it belongs in the contract</h2><p>When we are already delivering the framing, drywall, ceilings or tenant-improvement scope, we can also coordinate commercial carpet tile, resilient flooring and transitions. Flooring supports the main interior contract; it is not the focus of SteelStud.ca.</p><a href="/flooring">Commercial flooring add-on details →</a></div><img src="/images/archive/office-carpet-buildout-flooringinstaller.jpeg" alt="Commercial carpet tile installed as part of an office buildout"></div></section><section class="section"><div class="wrap split"><div><div class="eyebrow">Project evidence</div><h2>Real work, not stock-photo claims</h2><p class="lede">The project library documents completed and in-progress steel framing, drywall, T-bar, ceiling features, insulation and commercial interiors across the Lower Mainland.</p><a class="btn" href="/projects">Open the project gallery</a></div><img src="/images/real-tbar-ceiling-example.jpg" alt="Installed commercial suspended T-bar ceiling"></div></section>`}));

await emit("/framing-in-steel",page({path:"/framing-in-steel",title:"Steel Stud Framing Contractors Vancouver | Commercial Framing",description:"Commercial steel stud framing contractors in Vancouver and Metro Vancouver. Interior partitions, demising walls, bulkheads, backing, drywall and ceiling coordination.",json:[org,schema("Service",{name:"Commercial steel stud framing",serviceType:"Steel stud framing contractor",provider:{"@id":"https://www.steelstud.ca/#business"},areaServed:cities.map(c=>({"@type":"City",name:c.name}))}),framingFaqSchema],image:"/images/archive/building-suites.jpg",imageAlt:"Commercial steel stud framing in Metro Vancouver",body:`<div class="wrap crumbs"><a href="/">Home</a> / Steel stud framing</div><section class="page-hero"><div class="wrap"><div class="eyebrow">Commercial framing contractors · Metro Vancouver</div><h1>Steel stud framing contractors</h1><p class="lede">Straight, coordinated light-gauge steel framing for commercial interiors, offices, retail units, strata properties and multi-unit construction.</p><div class="actions"><a class="btn" href="tel:${business.phoneHref}">Discuss your framing scope</a><a class="btn alt" href="/projects">View framing projects</a></div></div></section><section class="section"><div class="wrap split"><div><h2>Commercial framing that protects every trade after it</h2><p>Partition layout establishes room sizes, corridors, door openings, glazing, millwork clearances and ceiling relationships. We build from the drawings and verified site conditions, then coordinate backing and service openings before board installation.</p><ul class="checklist"><li>Interior steel stud partitions and demising walls</li><li>Full-height, tall-wall and corridor framing</li><li>Bulkheads, soffits, drops and ceiling features</li><li>Door, glazing and access-panel openings</li><li>Backing, blocking and equipment supports</li><li>Fire-rated and acoustic assembly coordination</li></ul></div><img src="/images/archive/building-suites.jpg" alt="Steel stud walls and openings framed for a commercial interior"></div></section><section class="section alt"><div class="wrap"><div class="eyebrow">One coordinated assembly</div><h2>Framing, drywall and ceilings planned together</h2><div class="grid"><article class="card"><img src="/images/archive/steelstud-project-21.jpg" alt="Commercial steel stud partition framing"><div class="card-body"><h3>Partitions & openings</h3><p>Accurate walls, door frames, glazing openings and backing laid out around the finished plan.</p></div></article><article class="card"><img src="/images/service-drywall.png" alt="Drywall installed over steel framing"><div class="card-body"><h3>Drywall assemblies</h3><p>Board type, layers, joints, finish level and service penetrations coordinated before closure.</p><a href="/drywall">Drywall services →</a></div></article><article class="card"><img src="/images/real-tbar-ceiling-example.jpg" alt="Commercial suspended ceiling coordinated with partitions"><div class="card-body"><h3>Ceiling coordination</h3><p>Partition heads, ceiling elevations, lighting, diffusers and access requirements resolved together.</p><a href="/t-bar">Commercial ceilings →</a></div></article></div></div></section><section class="section"><div class="wrap split"><div><h2>Where steel framing fits best</h2><p>Steel studs are dimensionally stable, non-combustible and practical for commercial interiors where long walls, repeated layouts, services and precise finished dimensions matter. The member size, gauge, spacing, bracing and connections must match the required assembly and project documents.</p><p>SteelStud.ca serves Vancouver, Burnaby, Richmond, Surrey, the Tri-Cities, the North Shore and the Fraser Valley. See the <a href="/service-areas">full service area list</a> or discuss a tenant-improvement package.</p><a class="btn" href="/tenant-improvements">Tenant improvement services</a></div><img src="/images/archive/steelstud-2018-project-2.jpg" alt="Multi-storey commercial steel framing project"></div></section><section class="section alt faq"><div class="wrap"><h2>Steel stud framing questions</h2>${framingFaqs.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join("")}</div></section>`}));

await emit("/flooring",page({path:"/flooring",title:"Commercial Flooring Add-On | SteelStud.ca",description:"Commercial carpet tile, resilient flooring and transitions coordinated as part of a larger SteelStud.ca framing, drywall, ceiling or tenant-improvement contract.",json:[org,schema("Service",{name:"Commercial flooring add-on",serviceType:"Commercial flooring within interior construction contracts",provider:{"@id":"https://www.steelstud.ca/#business"},areaServed:cities.map(c=>c.name)})],image:"/images/archive/office-carpet-buildout-flooringinstaller.jpeg",imageAlt:"Commercial carpet tile in a completed office interior",body:`<div class="wrap crumbs"><a href="/">Home</a> / Commercial flooring add-on</div><section class="page-hero"><div class="wrap"><div class="eyebrow">Finishing scope for active interior contracts</div><h1>Commercial flooring add-on</h1><p class="lede">Carpet tile, resilient flooring and transitions available when flooring is part of a larger SteelStud.ca framing, drywall, ceiling or tenant-improvement contract.</p></div></section><section class="section"><div class="wrap split"><div><h2>Finish the commercial space under one coordinated scope</h2><p>When SteelStud.ca is already building the partitions, drywall or ceilings, adding the commercial floor can simplify sequencing, transitions and turnover. We review the substrate, finished elevations, door clearances and adjoining materials before installation.</p><ul class="checklist"><li>Commercial carpet tile</li><li>Luxury vinyl plank and resilient flooring</li><li>Floor preparation and transitions</li><li>Installation coordinated after walls and ceilings</li><li>Office, retail, strata and mixed-use interiors</li></ul><p>For a complete commercial buildout requiring broader multi-trade coordination, visit <a href="https://tenantimprovementcontractors.com/" rel="noopener">Tenant Improvement Contractors</a>.</p></div><img src="/images/archive/office-carpet-buildout-flooringinstaller.jpeg" alt="Completed office carpet tile installation"></div></section><section class="section alt"><div class="wrap"><h2>Part of the project—not the headline service</h2><p class="lede">SteelStud.ca remains focused on steel framing, drywall and ceilings. Flooring is offered where it improves delivery of the commercial interior contract.</p><p><a href="/framing-in-steel">Steel stud framing</a> · <a href="/drywall">Drywall</a> · <a href="/t-bar">Commercial ceilings</a> · <a href="/tenant-improvements">Tenant improvements</a></p></div></section>`}));
const soundproofingFaqs=[
  ["Does insulation alone soundproof a wall?","No. Acoustic batt can help absorb energy in the cavity, but effective sound control depends on the complete wall or ceiling assembly, including mass, separation, sealed perimeters and carefully treated penetrations."],
  ["Can SteelStud.ca build sound-control assemblies specified by a consultant?","Yes. We can frame, insulate, board and seal assemblies to the project documents, coordinating required layers, resilient components, penetrations and continuity with the responsible consultant or designer."],
  ["Do you provide soundproofing for offices and strata properties?","Yes. Common applications include meeting rooms, offices, demising walls, mechanical-room separations, suites and ceilings where reduced sound transfer is part of the renovation scope."],
];
