await emit("/soundproofing",page({path:"/soundproofing",title:"Soundproofing Contractors Vancouver | Acoustic Walls & Ceilings",description:"Soundproofing and acoustic wall and ceiling assemblies in Metro Vancouver: acoustic insulation, resilient channel, layered drywall and sealed penetrations.",json:[org,schema("Service",{name:"Soundproofing and acoustic assemblies",serviceType:"Soundproofing walls and ceilings",provider:{"@id":"https://www.steelstud.ca/#business"},areaServed:cities.map(c=>({"@type":"City",name:c.name}))}),soundproofingFaqSchema],image:"/images/archive/steelstud-projectmain.jpg",imageAlt:"Acoustic ceiling and sound-control construction",body:`<div class="wrap crumbs"><a href="/">Home</a> / Soundproofing</div><section class="page-hero"><div class="wrap"><div class="eyebrow">Acoustic wall and ceiling assemblies</div><h1>Soundproofing contractors</h1><p class="lede">Sound-control walls and ceilings built as complete assemblies—not sold as one miracle product.</p><div class="actions"><a class="btn" href="tel:${business.phoneHref}">Discuss the assembly</a><a class="btn alt" href="/projects">View project work</a></div></div></section><section class="section"><div class="wrap split"><div><h2>Mass, absorption, separation and sealed details</h2><p>Reducing sound transfer requires the framing, insulation, board layers, resilient components, perimeters and penetrations to work together. We coordinate those details before the walls or ceilings are closed.</p><ul class="checklist"><li>Acoustic batt insulation in walls and ceilings</li><li>Resilient channel and isolation details</li><li>Multiple-layer drywall assemblies</li><li>Acoustic sealant at perimeters and penetrations</li><li>Office, meeting-room and demising-wall sound control</li><li>Assemblies built to project or consultant requirements</li></ul></div><img src="/images/archive/steelstud-projectmain.jpg" alt="Suspended acoustic ceiling installation"></div></section><section class="section alt"><div class="wrap"><h2>Framing and drywall crews who understand the acoustic details</h2><div class="grid"><article class="card"><div class="card-body"><h3>Walls</h3><p>Stud layout, cavity insulation, resilient components, board layers and sealed edges coordinated as one system.</p><a href="/framing-in-steel">Steel framing →</a></div></article><article class="card"><div class="card-body"><h3>Ceilings</h3><p>Suspended acoustic ceilings, drywall ceilings and transitions coordinated around structure, lighting and building services.</p><a href="/t-bar">Ceiling systems →</a></div></article><article class="card"><div class="card-body"><h3>Specialist requirements</h3><p>Where testing, ratings or acoustic design are required, we build to the documented assembly and coordinate with the appropriate specialist.</p><a href="https://acustiq.ca/" rel="noopener">Acustiq specialist systems →</a></div></article></div></div></section><section class="section faq"><div class="wrap"><h2>Soundproofing questions</h2>${soundproofingFaqs.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join("")}</div></section>`}));

await emit("/",page({path:"/",title:"Commercial Framing, Drywall & Ceilings Vancouver | SteelStud.ca",description:"A Metro Vancouver framing and drywall company specializing in steel studs, commercial ceilings and soundproofing assemblies for general contractors and property projects.",json:[org],image:"/images/archive/building-suites.jpg",imageAlt:"Commercial steel stud framing by SteelStud.ca",body:`<section class="hero"><div class="wrap"><div class="eyebrow">Commercial trade contractor · Metro Vancouver</div><h1>Framing, drywall, ceilings & soundproofing</h1><p>A dependable framing and drywall company for general contractors, construction managers, strata projects and commercial property teams—with specialist experience in steel framing, ceiling systems and sound-control assemblies.</p><div class="actions"><a class="btn" href="tel:${business.phoneHref}">Call ${business.phone}</a><a class="btn alt" href="/projects">Review project evidence</a></div></div></section><section class="section"><div class="wrap"><div class="stats"><div class="stat"><strong>Trade partner</strong>GC and construction-manager scopes</div><div class="stat"><strong>Complete packages</strong>framing, board, tape and finish</div><div class="stat"><strong>Specialist depth</strong>ceilings and sound control</div></div></div></section><section class="section alt" id="services"><div class="wrap"><div class="eyebrow">Focused commercial capability</div><h2>A framing and drywall contractor that can carry the ceiling scope</h2><p class="lede">Hire SteelStud.ca for a straightforward framing or drywall package, or combine walls, ceilings, insulation and soundproofing under one coordinated trade scope.</p><div class="grid">${cards}</div></div></section><section class="section"><div class="wrap split"><div><div class="eyebrow">For general contractors</div><h2>Easy to slot into the project team</h2><p class="lede">We are not trying to replace the GC. SteelStud.ca can work as the framing and drywall trade, coordinate with mechanical, electrical, sprinkler, glazing and millwork crews, and deliver the assembly ready for the next stage.</p><ul class="checklist"><li>Commercial steel stud partitions and bulkheads</li><li>Boarding, taping and specified finish levels</li><li>T-bar, suspended and drywall ceiling systems</li><li>Backing, openings and service coordination</li><li>Acoustic insulation and sound-control assemblies</li><li>Phased work in occupied buildings</li></ul><a class="btn" href="/framing-in-steel">Commercial framing capabilities</a></div><img src="/images/archive/building-suites.jpg" alt="Steel stud partition framing for a commercial buildout"></div></section><section class="section alt"><div class="wrap"><div class="eyebrow">Specialist capability</div><h2>Ceilings and soundproofing are part of the package</h2><div class="grid"><article class="card"><img src="/images/real-tbar-ceiling-example.jpg" alt="Commercial T-bar acoustic ceiling"><div class="card-body"><h3>Suspended ceilings</h3><p>T-bar grid, acoustic panels and coordinated layouts for lighting, diffusers, sprinklers and access.</p><a href="/t-bar">Ceiling systems →</a></div></article><article class="card"><img src="/images/archive/lighting-effect.jpg" alt="Architectural dropped drywall ceiling"><div class="card-body"><h3>Drywall ceiling features</h3><p>Drops, bulkheads, lighting coves and architectural features framed and finished as part of the interior.</p><a href="/drop-ceilings">Dropped ceilings →</a></div></article><article class="card"><img src="/images/archive/steelstud-projectmain.jpg" alt="Acoustic ceiling construction"><div class="card-body"><h3>Sound-control assemblies</h3><p>Acoustic batt, resilient details, layered drywall and sealed penetrations coordinated as a complete wall or ceiling system.</p><a href="/soundproofing">Soundproofing →</a></div></article></div></div></section><section class="section"><div class="wrap split"><div><div class="eyebrow">Secondary finishing scope</div><h2>Commercial flooring when it helps finish the contract</h2><p>When we are already delivering the framing, drywall, ceiling or tenant-improvement scope, commercial carpet tile, resilient flooring and transitions can be included for coordinated turnover. Flooring remains secondary to the core trade package.</p><a href="/flooring">Commercial flooring add-on →</a></div><img src="/images/archive/office-carpet-buildout-flooringinstaller.jpeg" alt="Commercial carpet tile in a completed office buildout"></div></section>`}));

