await emit("/about",page({path:"/about",title:"About SteelStud.ca | Ceilings, Walls & Floors",description:"SteelStud.ca brings together 16 years of steel-stud specialization, 35 years of contracting and an extensive recovered Metro Vancouver project portfolio.",json:[org],body:`<div class="wrap crumbs"><a href="/">Home</a> / About</div><section class="page-hero"><div class="wrap"><h1>Experience behind every surface</h1><p class="lede">${business.yearsSteel} years focused on steel stud systems. ${business.yearsContracting} years solving construction problems across ceilings, walls and floors.</p></div></section><section class="section"><div class="wrap split"><div><h2>Interior construction without the runaround</h2><p>SteelStud.ca is a Vancouver construction company built around good service, quality workmanship and direct responsibility. Our background combines specialized framing knowledge with the broader perspective required to coordinate drywall, ceilings, insulation, flooring, bathrooms, services and finished spaces.</p><p>Repeat customers and referrals helped build the original business. That same standard continues today: understand the customer's needs, provide a clear scope, coordinate the work carefully and deliver skilled craftsmanship.</p><p>Our earlier SteelStud.ca, FlooringInstaller.ca and BathroomRemodel.ca websites were lost during the COVID period. Their archives now preserve real project history—from commercial framing and architectural ceilings to flooring, custom showers and complete renovations across the Lower Mainland.</p><p>For larger work, experience during estimating and preconstruction helps identify constructability, scheduling, material and trade-coordination issues before they become field problems.</p><p>SteelStud.ca brings that experience together under one clear promise: ceilings, walls and floors, planned carefully and built as a coordinated interior.</p><a class="btn" href="/projects">View the recovered project gallery</a></div><img src="/images/archive/steelstud-projectmain.jpg" alt="Recovered SteelStud.ca framing and renovation project"></div></section>`}));
await emit("/about",page({path:"/about",title:"About SteelStud.ca | Commercial Framing, Drywall & Ceilings",description:"SteelStud.ca combines 16 years of steel-stud specialization with 35 years of construction experience across Metro Vancouver commercial interiors.",json:[org],image:"/images/archive/building-suites.jpg",imageAlt:"SteelStud.ca commercial steel framing project",body:`<div class="wrap crumbs"><a href="/">Home</a> / About</div><section class="page-hero"><div class="wrap"><div class="eyebrow">Commercial interior experience</div><h1>Built around steel framing</h1><p class="lede">${business.yearsSteel} years focused on steel stud systems and ${business.yearsContracting} years solving construction problems across Metro Vancouver interiors.</p></div></section><section class="section"><div class="wrap split"><div><h2>Framing first, with the finished assembly in mind</h2><p>SteelStud.ca specializes in the commercial interior systems that define the space: steel stud partitions, drywall assemblies, T-bar ceilings, ceiling drops, insulation, backing and coordinated tenant-improvement work.</p><p>Our work begins with layout, existing conditions, access and the project documents. We coordinate openings, backing, services, board requirements and ceiling elevations before the walls close so later trades are not left solving preventable conflicts.</p><p>Repeat customers and referrals helped build the original business. The same standard continues today: understand the scope, communicate clearly, protect the property and deliver skilled work that is ready for the next trade or final turnover.</p><p>Commercial flooring can be included when it forms part of a larger interior contract. Broader multi-trade projects can connect with Tenant Improvement Contractors, and property-wide strata programs can connect with Strata Property Services as those businesses are strengthened.</p><a class="btn" href="/projects">View real project evidence</a></div><img src="/images/archive/building-suites.jpg" alt="Commercial steel stud wall framing by SteelStud.ca"></div></section>`}));
